+import http from "node:http";
+import path from "node:path";
+import { stat } from "node:fs/promises";
+import { createReadStream } from "node:fs";
+import { fileURLToPath } from "node:url";
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+const PUBLIC_DIR = path.join(__dirname, "public");
+
+const MIME_TYPES = {
+  ".css": "text/css; charset=utf-8",
+  ".html": "text/html; charset=utf-8",
+  ".ico": "image/x-icon",
+  ".js": "text/javascript; charset=utf-8",
+  ".json": "application/json; charset=utf-8",
+  ".png": "image/png",
+  ".svg": "image/svg+xml"
+};
+
+export const DEFAULT_PORT = 9999;
+
+function resolveFilePath(urlPath) {
+  const pathname = urlPath === "/" ? "/index.html" : urlPath;
+  const safeRelativePath = path.normalize(pathname).replace(/^(\.\.(\/|\\|$))+/, "");
+  const absolutePath = path.join(PUBLIC_DIR, safeRelativePath);
+
+  if (!absolutePath.startsWith(PUBLIC_DIR)) {
+    return null;
+  }
+  return absolutePath;
+}
+
+function sendFile(filePath, response) {
+  const extension = path.extname(filePath).toLowerCase();
+  const contentType = MIME_TYPES[extension] ?? "application/octet-stream";
+
+  response.writeHead(200, { "Content-Type": contentType });
+  createReadStream(filePath).pipe(response);
+}
+
+export function createAppServer() {
+  return http.createServer(async (request, response) => {
+    try {
+      const parsedUrl = new URL(request.url ?? "/", "http://127.0.0.1");
+      const filePath = resolveFilePath(parsedUrl.pathname);
+
+      if (!filePath) {
+        response.writeHead(403, { "Content-Type": "text/plain; charset=utf-8" });
+        response.end("Forbidden");
+        return;
+      }
+
+      const fileStats = await stat(filePath);
+      if (!fileStats.isFile()) {
+        response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
+        response.end("Not Found");
+        return;
+      }
+
+      sendFile(filePath, response);
+    } catch (error) {
+      response.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
+      response.end("Not Found");
+    }
+  });
+}
+
+if (process.argv[1] === fileURLToPath(import.meta.url)) {
+  const server = createAppServer();
+  server.listen(DEFAULT_PORT, () => {
+    console.log(`Beautiful frontend is running on http://localhost:${DEFAULT_PORT}`);
+  });
+}
*** End Patch

