 260: function normalizeIntent(prompt: string, modeHint?: ModelIntent): ModelIntent {
 261:     if (modeHint) {
 262:         return modeHint;
 263:     }
 264: 
 265:     const lower = prompt.toLowerCase();
 266:     const hasReasoning = REASONING_KEYWORDS.some(key => lower.includes(key));
 267:     const hasCoding = CODING_KEYWORDS.some(key => lower.includes(key));
 268:     const hasSpeed = SPEED_KEYWORDS.some(key => lower.includes(key));
 269: 
 270:     if (hasReasoning) {
 271:         return 'reasoning';
 272:     }
 273:     if (hasCoding) {
 274:         return 'coding';
 275:     }
 276:     if (hasSpeed) {
 277:         return 'speed';
 278:     }
 279:     return 'coding';
 280: }
