 282: function isLikelyModelName(name: string): boolean {
 283:     if (!MODEL_NAME_PATTERN.test(name)) {
 284:         return false;
 285:     }
 286: 
 287:     const lower = name.toLowerCase();
 288:     if (lower.includes('http://') || lower.includes('https://') || lower.endsWith('.svg')) {
 289:         return false;
 290:     }
 291:     if (lower.includes('sidebar') || lower.includes('extension') || lower.includes('avatar')) {
 292:         return false;
 293:     }
 294: 
 295:     return /[0-9]/.test(name) || /[-_/.]/.test(name);
 296: }
