 298: function isInternalUtilityModel(modelName: string): boolean {
 299:     const lower = modelName.toLowerCase();
 300:     if (INTERNAL_MODEL_EXACT.has(lower)) {
 301:         return true;
 302:     }
 303:     return INTERNAL_MODEL_PREFIXES.some(prefix => lower.startsWith(prefix));
 304: }
