 306: function collectModelCandidates(input: unknown, out: Set<string>): void {
 307:     if (typeof input === 'string') {
 308:         if (MODEL_HINT_REGEX.test(input) && input.length <= 120 && isLikelyModelName(input)) {
 309:             out.add(input);
 310:         }
 311:         return;
 312:     }
 313: 
 314:     if (Array.isArray(input)) {
 315:         for (const value of input) {
 316:             collectModelCandidates(value, out);
 317:         }
 318:         return;
 319:     }
 320: 
 321:     if (input && typeof input === 'object') {
 322:         const obj = input as Record<string, unknown>;
 323:         for (const value of Object.values(obj)) {
 324:             collectModelCandidates(value, out);
 325:         }
 326:     }
 327: }
