 329: function normalizeModelList(models: Iterable<string>): string[] {
 330:     const dedup = new Map<string, string>();
 331:     for (const model of models) {
 332:         if (!isLikelyModelName(model)) {
 333:             continue;
 334:         }
 335:         const lower = model.toLowerCase();
 336:         if (!dedup.has(lower)) {
 337:             dedup.set(lower, model);
 338:         }
 339:     }
 340:     return Array.from(dedup.values()).sort((a, b) => a.localeCompare(b));
 341: }
