 343: function scoreModel(modelName: string, intent: ModelIntent): number {
 344:     const name = modelName.toLowerCase();
 345:     let score = 0;
 346: 
 347:     if (isInternalUtilityModel(name)) {
 348:         score -= 200;
 349:     }
 350: 
 351:     const priorityList = INTENT_MODEL_PRIORITIES[intent];
 352:     const priorityIndex = priorityList.indexOf(name);
 353:     if (priorityIndex >= 0) {
 354:         score += (priorityList.length - priorityIndex) * 30;
 355:     }
 356: 
 357:     if (intent === 'coding') {
 358:         if (name.includes('coder') || name.includes('code')) {
 359:             score += 14;
 360:         }
 361:         if (name.includes('qwen') || name.includes('deepseek') || name.includes('doubao-seed')) {
 362:             score += 6;
 363:         }
 364:     }
 365: 
 366:     if (intent === 'reasoning') {
 367:         if (name.includes('deepseek') || name.includes('kimi')) {
 368:             score += 12;
 369:         }
 370:         if (name.includes('glm-5') || name.includes('m2.5')) {
 371:             score += 5;
 372:         }
 373:     }
 374: 
 375:     if (intent === 'speed') {
 376:         if (name.includes('glm-4.7') || name.includes('doubao_1_8')) {
 377:             score += 10;
 378:         }
 379:         if (name.includes('qwen-3.5') || name.includes('m2') || name.includes('k2')) {
 380:             score += 4;
 381:         }
 382:     }
 383: 
 384:     if (name.includes('preview') || name.includes('experimental')) {
 385:         score -= 2;
 386:     }
 387: 
 388:     return score;
 389: }
