 391: function pickBestModel(models: string[], intent: ModelIntent): string | null {
 392:     if (models.length === 0) {
 393:         return null;
 394:     }
 395: 
 396:     const nonInternal = models.filter(model => !isInternalUtilityModel(model));
 397:     const pool = nonInternal.length > 0 ? nonInternal : models;
 398: 
 399:     let best: { name: string; score: number } | null = null;
 400:     for (const model of pool) {
 401:         const score = scoreModel(model, intent);
 402:         if (!best || score > best.score) {
 403:             best = { name: model, score };
 404:         }
 405:     }
 406:     return best?.name ?? pool[0];
 407: }
