 417: function deepClone<T>(value: T): T {
 418:     return JSON.parse(JSON.stringify(value)) as T;
 419: }
 420: 
 421: function mutateModelFields(template: unknown, selectedModel: string): unknown {
 422:     if (!template || typeof template !== 'object') {
 423:         return template;
 424:     }
 425: 
 426:     const copy = deepClone(template);
 427:     const stack: unknown[] = [copy];
 428:     while (stack.length > 0) {
 429:         const current = stack.pop();
 430:         if (!current || typeof current !== 'object') {
 431:             continue;
 432:         }
 433:         if (Array.isArray(current)) {
 434:             for (const item of current) {
 435:                 stack.push(item);
 436:             }
 437:             continue;
 438:         }
 439: 
 440:         const obj = current as Record<string, unknown>;
 441:         for (const [key, value] of Object.entries(obj)) {
 442:             if (typeof value === 'string' && key.toLowerCase().includes('model')) {
 443:                 obj[key] = selectedModel;
 444:             } else if (value && typeof value === 'object') {
 445:                 stack.push(value);
 446:             }
 447:         }
 448:     }
 449:     return copy;
 450: }
