 464: function extractModelNamesFromJsonText(input: string, out: Set<string>): void {
 465:     const regex = /"name":"([A-Za-z0-9][A-Za-z0-9._/-]{1,79})"/g;
 466:     let match: RegExpExecArray | null = regex.exec(input);
 467:     while (match) {
 468:         const model = match[1];
 469:         if (isLikelyModelName(model)) {
 470:             out.add(model);
 471:         }
 472:         match = regex.exec(input);
 473:     }
 474: }
