 476: function extractModelNamesFromPayload(input: unknown, out: Set<string>): void {
 477:     if (Array.isArray(input)) {
 478:         for (const item of input) {
 479:             extractModelNamesFromPayload(item, out);
 480:         }
 481:         return;
 482:     }
 483: 
 484:     if (!input || typeof input !== 'object') {
 485:         return;
 486:     }
 487: 
 488:     const obj = input as Record<string, unknown>;
 489:     const maybeName = obj.name;
 490:     if (typeof maybeName === 'string' && isLikelyModelName(maybeName)) {
 491:         out.add(maybeName);
 492:     }
 493: 
 494:     for (const value of Object.values(obj)) {
 495:         if (value && typeof value === 'object') {
 496:             extractModelNamesFromPayload(value, out);
 497:         }
 498:     }
 499: }
