 501: function extractSelectedModelFromPayload(input: unknown): string | null {
 502:     if (!input || typeof input !== 'object' || Array.isArray(input)) {
 503:         return null;
 504:     }
 505: 
 506:     const obj = input as Record<string, unknown>;
 507:     const maybeName = obj.name;
 508:     if (typeof maybeName === 'string' && isLikelyModelName(maybeName)) {
 509:         return maybeName;
 510:     }
 511: 
 512:     const selectedModel = obj.selectedModel;
 513:     if (selectedModel && typeof selectedModel === 'object' && !Array.isArray(selectedModel)) {
 514:         const nested = selectedModel as Record<string, unknown>;
 515:         const nestedName = nested.name;
 516:         if (typeof nestedName === 'string' && isLikelyModelName(nestedName)) {
 517:             return nestedName;
 518:         }
 519:     }
 520: 
 521:     return null;
 522: }
