 547: function loadSqliteModule(): SqliteModuleLike | null {
 548:     try {
 549:         const candidate = require('node:sqlite') as Partial<SqliteModuleLike>;
 550:         if (candidate && typeof candidate.DatabaseSync === 'function') {
 551:             return candidate as SqliteModuleLike;
 552:         }
 553:     } catch {
 554:         return null;
 555:     }
 556:     return null;
 557: }
 558: 
 559: function readStateDbWithSqlite(dbPath: string, sqliteModule: SqliteModuleLike): StateDbProbeResult | null {
 560:     let db: SqliteDatabaseLike | null = null;
 561:     try {
 562:         db = new sqliteModule.DatabaseSync(dbPath, { readonly: true });
 563:         const rows = db.prepare(MODEL_LIST_SQL).all(
 564:             STATE_DB_KEY_PATTERNS[0],
 565:             STATE_DB_KEY_PATTERNS[1],
 566:             STATE_DB_KEY_PATTERNS[2]
 567:         );
 568: 
 569:         const modelSet = new Set<string>();
 570:         let selectedModel: string | null = null;
 571:         for (const row of rows) {
 572:             const key = typeof row.key === 'string' ? row.key : '';
 573:             const rawValue = typeof row.value === 'string' ? row.value : '';
 574:             if (!rawValue) {
 575:                 continue;
 576:             }
 577: 
 578:             const parsed = safeJsonParse(rawValue);
 579:             if (parsed !== null) {
 580:                 extractModelNamesFromPayload(parsed, modelSet);
 581:                 if (key.includes('selected_model')) {
 582:                     selectedModel = extractSelectedModelFromPayload(parsed) ?? selectedModel;
 583:                 }
 584:             } else {
 585:                 extractModelNamesFromJsonText(rawValue, modelSet);
 586:                 if (key.includes('selected_model')) {
 587:                     selectedModel = extractSelectedModelFromText(rawValue) ?? selectedModel;
 588:                 }
 589:             }
 590:         }
 591: 
 592:         const models = normalizeModelList(modelSet);
 593:         if (models.length === 0) {
 594:             return null;
 595:         }
 596: 
 597:         return {
 598:             models,
 599:             selectedModel,
 600:             sourcePath: dbPath,
 601:             method: 'sqlite'
 602:         };
 603:     } catch {
 604:         return null;
 605:     } finally {
 606:         try {
 607:             db?.close?.();
 608:         } catch {
 609:             // ignore close failures
 610:         }
 611:     }
 612: }
 613: 
 614: function readStateDbWithTextScan(dbPath: string): StateDbProbeResult | null {
 615:     try {
 616:         const content = fs.readFileSync(dbPath);
 617:         const text = content.toString('utf8');
 618:         const modelSet = new Set<string>();
 619:         extractModelNamesFromJsonText(text, modelSet);
 620:         const models = normalizeModelList(modelSet);
 621:         if (models.length === 0) {
 622:             return null;
 623:         }
 624:         return {
 625:             models,
 626:             selectedModel: null,
 627:             sourcePath: dbPath,
 628:             method: 'text-scan'
 629:         };
 630:     } catch {
 631:         return null;
 632:     }
 633: }
 634: 
 635: function readStateDbModels(details: string[]): StateDbProbeResult | null {
 636:     const dbPaths = resolveStateDbPaths();
 637:     if (dbPaths.length === 0) {
 638:         details.push('state.vscdb not found');
 639:         return null;
 640:     }
 641: 
 642:     const sqliteModule = loadSqliteModule();
 643:     if (sqliteModule) {
 644:         for (const dbPath of dbPaths) {
 645:             const result = readStateDbWithSqlite(dbPath, sqliteModule);
 646:             if (result) {
 647:                 details.push(`state.vscdb loaded via sqlite: ${result.sourcePath}`);
 648:                 return result;
 649:             }
 650:         }
 651:         details.push('state.vscdb sqlite read failed');
 652:     } else {
 653:         details.push('node:sqlite unavailable');
 654:     }
 655: 
 656:     for (const dbPath of dbPaths) {
 657:         const result = readStateDbWithTextScan(dbPath);
 658:         if (result) {
 659:             details.push(`state.vscdb loaded via text scan: ${result.sourcePath}`);
 660:             return result;
 661:         }
 662:     }
 663: 
 664:     details.push('state.vscdb text scan failed');
 665:     return null;
 666: }
