 681: async function autoSelectModel(payload: AutoSelectModelPayload): Promise<AutoSelectionResult> {
 682:     const details: string[] = [];
 683:     const prompt = (payload.prompt ?? '').trim();
 684:     const intent = normalizeIntent(prompt, payload.modeHint);
 685:     const candidateSet = new Set<string>();
 686: 
 687:     const allCommands = await vscode.commands.getCommands(true);
 688:     const hasGetConfig = allCommands.includes('icube.extended.integrations.llm.getConfig');
 689:     const hasSetConfig = allCommands.includes('icube.extended.integrations.llm.setConfig');
 690:     const hasOpenPicker = allCommands.includes('workbench.action.chat.openModelPicker');
 691: 
 692:     details.push(`intent=${intent}`);
 693:     details.push(`commands: getConfig=${hasGetConfig}, setConfig=${hasSetConfig}, openModelPicker=${hasOpenPicker}`);
 694: 
 695:     let currentConfig: unknown = null;
 696:     if (hasGetConfig) {
 697:         const configResult = await executeCommandSafely('icube.extended.integrations.llm.getConfig', []);
 698:         if (configResult.ok) {
 699:             currentConfig = configResult.value;
 700:             collectModelCandidates(configResult.value, candidateSet);
 701:             details.push('getConfig ok');
 702:         } else {
 703:             details.push(`getConfig failed: ${configResult.error}`);
 704:         }
 705:     }
 706: 
 707:     const stateDbResult = readStateDbModels(details);
 708:     if (stateDbResult) {
 709:         for (const model of stateDbResult.models) {
 710:             candidateSet.add(model);
 711:         }
 712:         details.push(`state models=${stateDbResult.models.length}`);
 713:         if (stateDbResult.selectedModel) {
 714:             details.push(`state selected=${stateDbResult.selectedModel}`);
 715:         }
 716:     }
 717: 
 718:     const candidateModels = normalizeModelList(candidateSet);
 719:     const selectedModel = pickBestModel(candidateModels, intent);
 720:     if (!selectedModel) {
 721:         if (hasOpenPicker) {
 722:             await executeCommandSafely('workbench.action.chat.openModelPicker', []);
 723:             details.push('no candidate models found; opened picker fallback');
 724:         }
 725:         return {
 726:             intent,
 727:             selectedModel: null,
 728:             candidateModels,
 729:             usedSetConfig: false,
 730:             setConfigSucceeded: false,
 731:             details: [...details, 'no model selected']
 732:         };
 733:     }
 734: 
 735:     details.push(`selected=${selectedModel}`);
 736: 
 737:     if (payload.dryRun) {
 738:         return {
 739:             intent,
 740:             selectedModel,
 741:             candidateModels,
 742:             usedSetConfig: false,
 743:             setConfigSucceeded: false,
 744:             details: [...details, 'dryRun=true, no model switch attempted']
 745:         };
 746:     }
 747: 
 748:     if (!hasSetConfig) {
 749:         if (hasOpenPicker) {
 750:             await executeCommandSafely('workbench.action.chat.openModelPicker', []);
 751:             details.push('setConfig missing, opened model picker as fallback');
 752:         }
 753:         return {
 754:             intent,
 755:             selectedModel,
 756:             candidateModels,
 757:             usedSetConfig: false,
 758:             setConfigSucceeded: false,
 759:             details
 760:         };
 761:     }
 762: 
 763:     const setConfigPayloads: unknown[] = [
 764:         { model: selectedModel },
 765:         { modelId: selectedModel },
 766:         { modelName: selectedModel },
 767:         { defaultModel: selectedModel },
 768:         { activeModel: selectedModel },
 769:         selectedModel
 770:     ];
 771:     if (currentConfig && typeof currentConfig === 'object') {
 772:         setConfigPayloads.push(mutateModelFields(currentConfig, selectedModel));
 773:     }
 774: 
 775:     let sawSetConfigOk = false;
 776:     for (const config of setConfigPayloads) {
 777:         const setRes = await executeCommandSafely('icube.extended.integrations.llm.setConfig', [config]);
 778:         details.push(`setConfig tried: ${safeStringify(config)} -> ${setRes.ok ? 'ok' : setRes.error}`);
 779:         if (!setRes.ok) {
 780:             continue;
 781:         }
 782: 
 783:         sawSetConfigOk = true;
 784:         await sleep(120);
