function connect(url, timeoutMs = 8000) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    const timer = setTimeout(() => {
      try { ws.close(); } catch {}
      reject(new Error("connect timeout"));
    }, timeoutMs);

    ws.addEventListener("open", () => {
      clearTimeout(timer);
      resolve(ws);
    });
    ws.addEventListener("error", (e) => {
      clearTimeout(timer);
      reject(new Error(`connect error: ${e.message || "unknown"}`));
    }, { once: true });
  });
}

function createInbox(ws, summary) {
  const queue = [];
  const waiters = [];

  ws.addEventListener("message", (event) => {
    let data;
    try {
      data = JSON.parse(String(event.data));
    } catch {
      data = { type: "raw", data: String(event.data) };
    }

    summary.rx.push(data);
    if (waiters.length > 0) {
      const waiter = waiters.shift();
      waiter(data);
      return;
    }
    queue.push(data);
  });

  function nextMessage(timeoutMs) {
    if (queue.length > 0) {
      return Promise.resolve(queue.shift());
    }
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        const idx = waiters.indexOf(onData);
        if (idx >= 0) waiters.splice(idx, 1);
        reject(new Error("timeout waiting ws message"));
      }, timeoutMs);

      function onData(msg) {
        clearTimeout(timer);
        resolve(msg);
      }
      waiters.push(onData);
    });
  }

  return { nextMessage };
}

async function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function sendWithRetry(ws, inbox, payload, matchFn, label, summary) {
  let lastErr = null;

  for (let attempt = 1; attempt <= 3; attempt++) {
    const attemptPayload = { ...payload, retry: attempt - 1 };
    ws.send(JSON.stringify(attemptPayload));
    summary.tx.push(attemptPayload);

    try {
      const deadline = Date.now() + stepTimeoutMs;
      while (Date.now() < deadline) {
        const left = Math.max(1, deadline - Date.now());
        const msg = await inbox.nextMessage(left);
        if (matchFn(msg)) {
          return { ok: true, attempt, msg };
        }
      }
      lastErr = new Error(`${label} timeout`);
    } catch (err) {
      lastErr = err;
    }

    if (attempt < 3) {
      await sleep(retryBackoff[attempt - 1]);
    }
  }

  return { ok: false, error: String(lastErr) };
}

