      summary.blocked = {
        task_id: task.task_id,
        reason: "no_available_model",
        detail: modelSelectRes.msg
      };
      break;
    }

    const dispatchRes = await sendWithRetry(
      ws,
      inbox,
      {
        action: "trigger_task",
        waveId,
