    summary.rx.push(data);
    if (waiters.length > 0) {
      const waiter = waiters.shift();
      waiter(data);
      return;
    }
    queue.push(data);
  });

  return {
    next(timeoutMs) {
      if (queue.length > 0) {
        return Promise.resolve(queue.shift());
      }
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          const idx = waiters.indexOf(onData);
          if (idx >= 0) waiters.splice(idx, 1);
          reject(new Error("timeout waiting message"));
        }, timeoutMs);
        function onData(msg) { clearTimeout(timer); resolve(msg); }
        waiters.push(onData);
      });
    }
  };
}

async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function sendWithRetry(ws, inbox, payload, matcher, label, summary) {
  const backoff = [1000, 2000, 4000];
  for (let i = 0; i < 3; i++) {
    const msg = { ...payload, retry: i };
    ws.send(JSON.stringify(msg));
    summary.tx.push(msg);

    const end = Date.now() + 20000;
    while (Date.now() < end) {
      const left = Math.max(1, end - Date.now());
      try {
        const incoming = await inbox.next(left);
        if (matcher(incoming)) {
          return { ok: true, attempt: i + 1, msg: incoming };
        }
      } catch {
        break;
      }
    }

    if (i < 2) await sleep(backoff[i]);
  }
  return { ok: false };
}

